<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';
$me=require_login();
$canManage=can('live.manage');$canUpdate=can('live.update');$canApprove=can('live.approve');
if(!$canManage&&!$canUpdate&&!$canApprove){http_response_code(403);exit('Live newsroom permission required.');}
$error='';$eventId=max(0,(int)($_GET['event']??0));
function live_admin_redirect(int $eventId=0):never{header('Location: '.path('admin/live-operations.php'.($eventId?'?event='.$eventId:'')));exit;}
function live_admin_notify(int $userId,string $title,string $body,int $updateId):void{db()->prepare("INSERT INTO notifications(user_id,notification_type,title,body,entity_type,entity_id) VALUES (?,'live_update',?,?,'live_update',?)")->execute([$userId,substr($title,0,240),substr($body,0,1000),$updateId]);}
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_verify();$action=(string)($_POST['action']??'');
 try{
  if($action==='create_event'){
   if(!$canManage)throw new RuntimeException('Live-event management permission required.');$title=trim((string)($_POST['title']??''));$summary=trim((string)($_POST['summary']??''));$slug=substr(slugify(trim((string)($_POST['slug']??''))?:$title),0,240);
   if(mb_strlen($title)<10||mb_strlen($summary)<20)throw new RuntimeException('Title and a meaningful summary are required.');if(query_one('SELECT id FROM live_events WHERE slug=?',[$slug]))throw new RuntimeException('Live-event slug already exists.');
   db()->prepare("INSERT INTO live_events(title,slug,summary,status,created_by) VALUES (?,?,?,'draft',?)")->execute([$title,$slug,$summary,(int)$me['id']]);$id=(int)db()->lastInsertId();audit_log('live_event_created','live_event',$id,$slug);flash('Live event draft created.');live_admin_redirect($id);
  }
  if($action==='event_status'){
   if(!$canManage)throw new RuntimeException('Live-event management permission required.');$id=(int)($_POST['id']??0);$to=(string)($_POST['status']??'');$event=query_one('SELECT * FROM live_events WHERE id=?',[$id]);if(!$event)throw new RuntimeException('Live event missing.');$from=(string)$event['status'];$allowed=['draft'=>['live'],'live'=>['closed'],'closed'=>['archived']];if(!in_array($to,$allowed[$from]??[],true))throw new RuntimeException('Invalid live-event transition.');
   $started=$to==='live'?date('Y-m-d H:i:s'):($event['started_at']??null);$closed=$to==='closed'?date('Y-m-d H:i:s'):($event['closed_at']??null);$s=db()->prepare('UPDATE live_events SET status=?,editor_id=?,started_at=?,closed_at=? WHERE id=? AND status=?');$s->execute([$to,(int)$me['id'],$started,$closed,$id,$from]);if($s->rowCount()!==1)throw new RuntimeException('Live event changed concurrently.');audit_log('live_event_status','live_event',$id,$from.'>'.$to);flash('Live event status updated.');live_admin_redirect($id);
  }
  if($action==='create_update'){
   if(!$canUpdate)throw new RuntimeException('Live-update permission required.');$id=(int)($_POST['event_id']??0);$event=query_one("SELECT id FROM live_events WHERE id=? AND status='live'",[$id]);$body=trim((string)($_POST['body']??''));if(!$event||mb_strlen($body)<10||mb_strlen($body)>10000)throw new RuntimeException('A live event and update of 10–10,000 characters are required.');
   db()->prepare("INSERT INTO live_updates(live_event_id,body,status,author_id) VALUES (?,?,'draft',?)")->execute([$id,$body,(int)$me['id']]);$updateId=(int)db()->lastInsertId();audit_log('live_update_drafted','live_update',$updateId,'event:'.$id);flash('Live update saved as draft for independent approval.');live_admin_redirect($id);
  }
  if($action==='approve_update'){
   if(!$canApprove)throw new RuntimeException('Live approval permission required.');$id=(int)($_POST['id']??0);$update=query_one("SELECT * FROM live_updates WHERE id=? AND status='draft'",[$id]);if(!$update)throw new RuntimeException('Draft update missing.');if((int)$update['author_id']===(int)$me['id'])throw new RuntimeException('An update author cannot approve the same update.');
   $s=db()->prepare("UPDATE live_updates SET status='approved',approved_by=?,published_at=? WHERE id=? AND status='draft'");$s->execute([(int)$me['id'],date('Y-m-d H:i:s'),$id]);if($s->rowCount()!==1)throw new RuntimeException('Update changed concurrently.');live_admin_notify((int)$update['author_id'],'Live update approved','Your live update is now public.',$id);audit_log('live_update_approved','live_update',$id);flash('Update approved and published.');live_admin_redirect((int)$update['live_event_id']);
  }
  if($action==='moderate_update'){
   if(!$canApprove)throw new RuntimeException('Live moderation permission required.');$id=(int)($_POST['id']??0);$to=(string)($_POST['status']??'');$note=trim((string)($_POST['note']??''));$update=query_one("SELECT * FROM live_updates WHERE id=? AND status IN ('approved','corrected')",[$id]);if(!$update||!in_array($to,['corrected','withdrawn'],true)||mb_strlen($note)<10)throw new RuntimeException('Published update, valid action and reason of at least 10 characters are required.');
   $s=db()->prepare("UPDATE live_updates SET status=?,correction_note=? WHERE id=? AND status IN ('approved','corrected')");$s->execute([$to,substr($note,0,1000),$id]);if($s->rowCount()!==1)throw new RuntimeException('Update changed concurrently.');live_admin_notify((int)$update['author_id'],'Live update '.$to,$note,$id);audit_log('live_update_'.$to,'live_update',$id,$note);flash('Live update moderation recorded.');live_admin_redirect((int)$update['live_event_id']);
  }
  if($action==='toggle_pin'){
   if(!$canApprove)throw new RuntimeException('Live moderation permission required.');$id=(int)($_POST['id']??0);$update=query_one("SELECT * FROM live_updates WHERE id=? AND status IN ('approved','corrected')",[$id]);if(!$update)throw new RuntimeException('Published update missing.');db()->prepare('UPDATE live_updates SET is_pinned=? WHERE id=?')->execute([(int)$update['is_pinned']?0:1,$id]);audit_log('live_update_pin','live_update',$id,(int)$update['is_pinned']?'off':'on');flash('Pinned status updated.');live_admin_redirect((int)$update['live_event_id']);
  }
  throw new RuntimeException('Unknown live operation.');
 }catch(Throwable $e){$error=$e->getMessage();$eventId=(int)($_POST['event_id']??$_POST['live_event_id']??$eventId);}
}
$events=query_all('SELECT le.*,u.full_name creator_name,e.full_name editor_name,(SELECT COUNT(*) FROM live_updates lu WHERE lu.live_event_id=le.id AND lu.status=\'draft\') pending_updates FROM live_events le JOIN users u ON u.id=le.created_by LEFT JOIN users e ON e.id=le.editor_id ORDER BY le.created_at DESC LIMIT 100');
$selected=$eventId?query_one('SELECT * FROM live_events WHERE id=?',[$eventId]):($events[0]??null);if($selected)$eventId=(int)$selected['id'];
$updates=$selected?query_all('SELECT lu.*,u.full_name author_name,a.full_name approver_name FROM live_updates lu JOIN users u ON u.id=lu.author_id LEFT JOIN users a ON a.id=lu.approved_by WHERE lu.live_event_id=? ORDER BY lu.created_at DESC LIMIT 300',[$eventId]):[];
?><!doctype html><html lang="rw"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Live Operations · AFRIVOX NEWS</title><link rel="stylesheet" href="<?=e(path('assets/style.css'))?>"><link rel="stylesheet" href="<?=e(path('assets/admin.css'))?>"></head><body class="admin-body"><main class="admin-content" style="max-width:1250px;margin:auto"><p><a href="<?=e(path('admin/index.php'))?>">← Newsroom</a> · <a href="<?=e(path('live.php'))?>" target="_blank" rel="noopener">Public live page ↗</a></p><div class="admin-section-title"><h1>Live operations<span class="brand-accent">.</span></h1></div><p>Updates remain drafts until approved by a different authorized editor. Corrections preserve the original body and add a public correction note.</p><?php if($error):?><div class="form-error" role="alert"><?=e($error)?></div><?php endif;?><?php if($msg=notice()):?><div class="admin-notice" role="status"><?=e($msg)?></div><?php endif;?><?php if($canManage):?><section class="setting-panel"><h2>Create event draft</h2><form method="post" class="public-form"><?=csrf_field()?><input type="hidden" name="action" value="create_event"><label>TITLE<input name="title" minlength="10" maxlength="240" required></label><label>SLUG (OPTIONAL)<input name="slug" maxlength="240"></label><label>SUMMARY<textarea name="summary" minlength="20" maxlength="5000" required></textarea></label><button>CREATE EVENT</button></form></section><?php endif;?><div class="workflow-grid"><section class="setting-panel"><h2>Events</h2><?php foreach($events as $event):?><p><a href="?event=<?=$event['id']?>"><b><?=e($event['title'])?></b></a><br><small><?=e($event['status'])?> · pending <?=(int)$event['pending_updates']?> · <?=e(display_date($event['created_at']))?></small></p><?php endforeach;?></section><?php if($selected):?><section class="setting-panel"><h2><?=e($selected['title'])?></h2><p><?=e($selected['summary'])?></p><p><b>Status:</b> <?=e($selected['status'])?></p><?php if($canManage):$next=['draft'=>'live','live'=>'closed','closed'=>'archived'][$selected['status']]??null;if($next):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="event_status"><input type="hidden" name="id" value="<?=$selected['id']?>"><input type="hidden" name="status" value="<?=e($next)?>"><button><?=e(strtoupper($next))?> EVENT</button></form><?php endif;endif;?><?php if($canUpdate&&$selected['status']==='live'):?><form method="post" class="public-form"><?=csrf_field()?><input type="hidden" name="action" value="create_update"><input type="hidden" name="event_id" value="<?=$selected['id']?>"><label>NEW UPDATE<textarea name="body" minlength="10" maxlength="10000" required></textarea></label><button>SAVE DRAFT UPDATE</button></form><?php endif;?></section><?php endif;?></div><?php if($selected):?><section class="setting-panel"><h2>Update queue</h2><?php foreach($updates as $update):?><article class="inbox-card"><small><?=e(display_date($update['created_at']))?> · <?=e($update['author_name'])?> · <b><?=e($update['status'])?></b><?=$update['is_pinned']?' · PINNED':''?></small><p><?=nl2br(e($update['body']))?></p><?php if($update['correction_note']):?><p class="correction"><b>Moderation note:</b> <?=e($update['correction_note'])?></p><?php endif;?><?php if($canApprove&&$update['status']==='draft'&&(int)$update['author_id']!==(int)$me['id']):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="approve_update"><input type="hidden" name="id" value="<?=$update['id']?>"><input type="hidden" name="event_id" value="<?=$selected['id']?>"><button>APPROVE & PUBLISH</button></form><?php endif;?><?php if($canApprove&&in_array($update['status'],['approved','corrected'],true)):?><form method="post" class="public-form"><?=csrf_field()?><input type="hidden" name="action" value="moderate_update"><input type="hidden" name="id" value="<?=$update['id']?>"><input type="hidden" name="event_id" value="<?=$selected['id']?>"><label>ACTION<select name="status"><option value="corrected">Add correction note</option><option value="withdrawn">Withdraw update</option></select></label><label>PUBLIC REASON<input name="note" minlength="10" maxlength="1000" required></label><button>RECORD ACTION</button></form><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle_pin"><input type="hidden" name="id" value="<?=$update['id']?>"><input type="hidden" name="event_id" value="<?=$selected['id']?>"><button><?=$update['is_pinned']?'UNPIN':'PIN'?></button></form><?php endif;?></article><?php endforeach;?></section><?php endif;?></main></body></html>
